import fs from 'node:fs';import{createHash}from'node:crypto';import{resolve,join}from'node:path';import{readRetainedAsset}from'../../services/vii-edge-delivery/src/retained-assets.ts';
const account='45b2f6dcf2cfe44204d2c470cbe682d9',bucket='vii-public-document-cache',directory=resolve('.qa-output/phase14-active-assets'),op=resolve('.qa-output/phase14-seed-operation.json');
