const manifest=JSON.parse(fs.readFileSync(join(directory,'manifest.json'),'utf8'));
if(manifest.stage!=='captured-active-client-inventory'||manifest.origin!=='https://vii.spaplus.co'||manifest.buildId!=='00bca36c-4f1c-403d-9a13-ceea797015ae'||manifest.source!=='a29886dea2cd6589b6e65ae43969b976c033dab6'||manifest.publicDeployment!=='appgdep_6aecb13052d88191855eeb89c2e0427e'||manifest.publicBuildStableBeforeAfter!==true||manifest.manifestStableBeforeAfter!==true||manifest.fileCount!==manifest.files.length||manifest.fileCount>500||manifest.totalBytes>32*1024*1024||Date.now()-Date.parse(manifest.preparedAt)>3600000||Date.parse(manifest.retainUntil)<=Date.now())throw Error('Active inventory proof invalid');
const original=fs.readFileSync(join(directory,'observed-client-manifest.json'));const sha=b=>createHash('sha256').update(b).digest('hex');if(sha(original)!==manifest.manifestSha256)throw Error('Captured manifest changed');
if(new Set(manifest.files.map(x=>x.key)).size!==manifest.files.length)throw Error('Duplicate object key');
for(const row of manifest.files){if(!/^retained-assets-v1\/[a-f0-9]{64}$/.test(row.key))throw Error('Namespace outside retention');const bytes=fs.readFileSync(join(directory,row.key.split('/')[1]+'.bin'));if(bytes.length!==row.envelopeBytes||sha(bytes)!==row.envelopeSha256)throw Error('Local envelope changed');const response=await readRetainedAsset(new Request(manifest.origin+row.path),{async get(){return{size:bytes.length,body:new Blob([bytes]).stream()}}});if(!response||sha(new Uint8Array(await response.arrayBuffer()))!==row.sha256)throw Error('Local body identity mismatch');}
const start=Date.now(),deadline=start+240000,state={operation:'phase14-seed-exact-active-client-assets-private-r2',attempt:1,status:'preflight',accountId:account,bucket,source:manifest.source,buildId:manifest.buildId,manifestSha256:manifest.manifestSha256,startedAt:new Date(start).toISOString(),deadline:new Date(deadline).toISOString(),publicRouteChanged:false,entries:manifest.files.map(row=>({key:row.key,sha256:row.envelopeSha256,status:'not_attempted'}))};
function save(){const temp=op+'.tmp',fd=fs.openSync(temp,'w');try{fs.writeFileSync(fd,JSON.stringify(state,null,2));fs.fsyncSync(fd);}finally{fs.closeSync(fd);}fs.renameSync(temp,op);}
async function api(path,{method='GET',bytes}={}){if(Date.now()>=deadline)throw Error('Storage deadline');const r=await fetch('https://api.cloudflare.com/client/v4/accounts/'+account+path,{method,redirect:'manual',headers:{Authorization:'Bearer '+token,...(method==='PUT'?{'cf-r2-data-catalog-check':'true','Content-Type':'application/octet-stream'}:{})},...(bytes?{body:bytes}:{}),signal:AbortSignal.timeout(Math.min(15000,deadline-Date.now()))});return r;}
async function metadata(path){const r=await api(path);if(!r.ok)throw Error('Cloud resource read status '+r.status);const p=await r.json();if(!p.success)throw Error('Cloud resource identity unavailable');return p.result;}
const meta=await metadata('/r2/buckets/'+bucket);if(meta.name!==bucket)throw Error('Bucket identity mismatch');const dev=await metadata('/r2/buckets/'+bucket+'/domains/managed'),custom=await metadata('/r2/buckets/'+bucket+'/domains/custom');if(dev.enabled!==false||!Array.isArray(custom.domains)||custom.domains.length!==0)throw Error('Bucket unexpectedly public');
