save();let cursor=0,stopped=false;
async function bytesOf(response){if(!response.ok)throw Error('Storage HTTP '+response.status);const reader=response.body.getReader(),parts=[];let n=0;try{while(true){const p=await reader.read();if(p.done)break;n+=p.value.length;if(n>8*1024*1024+4100){void reader.cancel();throw Error('Stored object oversized');}parts.push(p.value);}}finally{reader.releaseLock();}return Buffer.concat(parts);}
const results=await Promise.allSettled(Array.from({length:4},async()=>{while(!stopped&&cursor<manifest.files.length){const index=cursor++,row=manifest.files[index],entry=state.entries[index],path='/r2/buckets/'+bucket+'/objects/'+row.key;try{entry.status='checking_existing';save();const existing=await api(path);if(existing.status===200){if(sha(await bytesOf(existing))!==row.envelopeSha256)throw Error('Existing retained key differs; no overwrite');entry.status='already_verified';save();continue;}if(existing.status!==404)throw Error('Existing object read HTTP '+existing.status);void existing.body?.cancel();entry.status='put_in_flight';entry.startedAt=new Date().toISOString();save();const bytes=fs.readFileSync(join(directory,row.key.split('/')[1]+'.bin')),put=await api(path,{method:'PUT',bytes});if(!put.ok){void put.body?.cancel();throw Error('PUT not acknowledged HTTP '+put.status);}void put.body?.cancel();entry.status='acknowledged_pending_readback';save();const readback=await api(path);if(sha(await bytesOf(readback))!==row.envelopeSha256)throw Error('Readback mismatch');entry.status='stored_readback_verified';entry.finishedAt=new Date().toISOString();save();}catch(error){stopped=true;entry.previousStatus=entry.status;entry.status='unknown_or_failed';entry.reason=error.message;save();throw error;}}}));
state.status=results.some(x=>x.status==='rejected')?'partial_requires_original_outcome_review':'all_objects_private_readback_verified';state.finishedAt=new Date().toISOString();state.verified=state.entries.filter(x=>['stored_readback_verified','already_verified'].includes(x.status)).length;save();console.log(JSON.stringify({status:state.status,verified:state.verified,total:manifest.fileCount,accountId:account,bucket,manifestSha256:state.manifestSha256,publicRouteChanged:false,notificationsSent:0}));if(state.verified!==manifest.fileCount)process.exitCode=1;


